    /**
     * Which package to use for type resolution.
     * 'typescript' uses the installed typescript package.
     * 'typescript-go' uses the faster native binary if installed.
     * @default 'auto' — tries typescript-go first, falls back to typescript
     */
    engine: 'auto',  // | 'typescript' | 'typescript-go'

    /**
     * Max time to wait for a typescript-go response per batch.
     * If exceeded, affected types degrade to Opaque.
     * @default 5000 (5 seconds)
     */
    timeoutMs: 5000,
  }
})
