66	                        exported_name: binding.exported_name.clone(),
67	                        is_type_only: binding.is_type_only,
68	                    },
69	                );
70	            }
71	        }
72	
73	        // ── Populate wildcard_sources from re_export_map ──────────────────
74	        for (file_path, exports) in &global.re_export_map {
75	            for export in exports {
76	                if let LexedExport::ReExportAll { source_specifier, .. } = export {
77	                    wildcard_sources
78	                        .entry(file_path.clone())
79	                        .or_default()
80	                        .push(source_specifier.clone());
81	                }
82	            }
