    return true
  } catch {
    return false
  }
})()

describe.skipIf(!hasBinary)('NAPI integration', () => {
  let { extractAll, createSession, initializeSession, closeSession } = {} as typeof import('../index')

  beforeAll(async () => {
    const mod = await import('../index')
    extractAll = mod.extractAll
    createSession = mod.createSession
    initializeSession = mod.initializeSession
    closeSession = mod.closeSession
  })

  it('extractAll returns valid JSON with empty src_dirs', async () => {
    const result = await extractAll({ srcDirs: [] })
    const parsed = JSON.parse(result)
    expect(parsed).toHaveProperty('components')
    expect(parsed).toHaveProperty('diagnostics')
  })

  it('session lifecycle: create → initialize → close', async () => {
    const id = createSession({ srcDirs: [] })
    expect(typeof id).toBe('number')
    const result = await initializeSession(id, { srcDirs: [] })
    const parsed = JSON.parse(result)
    expect(parsed.components).toBeDefined()
    closeSession(id)
  })
})
