3	/// Find and load docgen.config.ts, walking up from start_dir to workspace root.
4	pub fn load_config_file(start_dir: &std::path::Path) -> Option<PipelineOptions> {
5	    let mut dir = start_dir;
6	    loop {
7	        let candidate = dir.join("docgen.config.ts");
8	        if candidate.exists() {
9	            return try_load_config(&candidate);
10	        }
11	        // Stop at workspace root signals
12	        for signal in &["pnpm-workspace.yaml", "turbo.json", ".moon/workspace.yml"] {
13	            if dir.join(signal).exists() {
14	                return None;
15	            }
16	        }
17	        dir = dir.parent()?;
18	    }
19	}
20	
21	pub fn try_load_config(path: &std::path::Path) -> Option<PipelineOptions> {
22	    use std::io::Write;
23	
24	    // Pass the config path via environment variable to avoid any path content
25	    // being interpreted as JavaScript (command injection via crafted filenames).
26	    let script = "import { pathToFileURL } from 'node:url';\
27	        const p = process.env.__DOCGEN_CONFIG_PATH;\
28	        const m = await import(pathToFileURL(p).href);\
29	        process.stdout.write(JSON.stringify(m.default ?? m));";
30	
31	    let mut child = std::process::Command::new("node")
32	        .args(["--input-type=module"])
33	        .env("NODE_OPTIONS", "--import=tsx/esm")
34	        .env("__DOCGEN_CONFIG_PATH", path)
35	        .stdin(std::process::Stdio::piped())
36	        .stdout(std::process::Stdio::piped())
37	        .stderr(std::process::Stdio::null())
38	        .spawn()
39	        .ok()?;
40	
41	    // Write the script to stdin, then close stdin to signal EOF.
42	    child.stdin.as_mut()?.write_all(script.as_bytes()).ok()?;
43	    drop(child.stdin.take());
44	
45	    let output = child.wait_with_output().ok()?;
46	
47	    if !output.status.success() {
48	        return None;
49	    }
50	
51	    // Parse as JSON value to validate; full mapping is a future TODO
52	    serde_json::from_slice::<serde_json::Value>(&output.stdout).ok()?;
53	    // TODO: map JSON fields to PipelineOptions
54	    None // stub — returns None until full config schema is mapped
55	}
