52	pub(super) fn parse_jsdoc_text(raw: &str) -> String {
53	    // Strip `/**` prefix and `*/` suffix
54	    let inner = raw.trim_start_matches("/**").trim_end_matches("*/");
55	
56	    let desc_lines: Vec<&str> = inner
57	        .lines()
58	        .map(|l| {
59	            let l = l.trim();
60	            // Strip leading `* ` or `*`
61	            let l = l.strip_prefix("* ").or_else(|| l.strip_prefix('*')).unwrap_or(l);
62	            l
63	        })
64	        .take_while(|l| !l.starts_with('@'))
65	        .collect();
66	
