12	// ─── ResolveState ─────────────────────────────────────────────────────────────
13	
14	/// Mutable resolution state threaded through all resolver functions.
15	/// Bundles the two fields that every recursive resolver function needs,
16	/// eliminating long argument signatures.
17	#[derive(Default)]
18	pub(crate) struct ResolveState {
19	    /// Cycle-detection set: "${file}:${type_name}" keys.
20	    pub(crate) visited: FxHashSet<CompactString>,
21	    /// Accumulated non-fatal issues.
22	    pub(crate) diagnostics: Vec<Diagnostic>,
23	}
24	
25	// ─── GlobalSourceData ─────────────────────────────────────────────────────────
26	
27	/// Merged source data from all files — the shared resolution context.
28	/// Built once, then read by all parallel resolution workers.
29	/// Uses Arc in pipeline — clone is cheap.
30	#[derive(Debug, Default, Clone)]
31	pub struct GlobalSourceData {
32	    /// All interfaces across all files.
33	    /// Key: "${absolute_file_path}:${name}" — always scoped, never bare
34	    pub interfaces: FxHashMap<String, CollectedInterface>,
35	
36	    /// All type aliases across all files.
37	    /// Key: "${absolute_file_path}:${name}"
38	    pub type_aliases: FxHashMap<String, CollectedTypeAlias>,
39	
40	    /// All enum-like definitions across all files.
41	    /// Key: "${absolute_file_path}:${name}"
42	    pub enums: FxHashMap<String, Vec<EnumEntry>>,
43	
44	    /// Import resolution map: file → [ImportBinding]
45	    pub import_map: FxHashMap<Utf8PathBuf, Vec<ImportBinding>>,
46	
47	    /// Re-export map: file → [LexedExport]
48	    pub re_export_map: FxHashMap<Utf8PathBuf, Vec<LexedExport>>,
49	
50	    /// All component mappings discovered
51	    pub component_mappings: Vec<ComponentMapping>,
52	}
53	
54	impl GlobalSourceData {
55	    /// Merge a single file's SourceData into the global data.
56	    pub fn merge(&mut self, file_path: &Utf8Path, data: SourceData) {
57	        for (key, iface) in data.interfaces {
58	            match self.interfaces.entry(key) {
59	                std::collections::hash_map::Entry::Occupied(mut e) => {
60	                    // Declaration merging: combine props and extends
61	                    let existing = e.get_mut();
62	                    existing.props.extend(iface.props);
63	                    existing.extends.extend(iface.extends);
64	                }
65	                std::collections::hash_map::Entry::Vacant(e) => {
66	                    e.insert(iface);
67	                }
68	            }
69	        }
70	        self.type_aliases.extend(data.type_aliases);
71	        self.enums.extend(data.enums);
72	        self.import_map.insert(file_path.to_owned(), data.imports);
73	        self.re_export_map.insert(file_path.to_owned(), data.exports);
74	        self.component_mappings.extend(data.component_mappings);
75	    }
76	
77	    /// Remove all entries contributed by `file_path`. Called before re-merging an updated file.
78	    pub fn remove_file(&mut self, file_path: &Utf8Path) {
79	        let prefix = format!("{}:", file_path);
80	        self.interfaces.retain(|k, _| !k.starts_with(&prefix));
81	        self.type_aliases.retain(|k, _| !k.starts_with(&prefix));
82	        self.enums.retain(|k, _| !k.starts_with(&prefix));
83	        self.import_map.remove(file_path);
84	        self.re_export_map.remove(file_path);
85	        self.component_mappings.retain(|m| m.file_path != file_path);
86	    }
87	}
