32	///
33	/// Completely pure — no I/O, no side effects, no cross-file dependencies.
34	/// Safe to call in parallel from rayon workers.
35	pub fn parse_file(path: &Utf8Path, source: &str) -> SourceData {
36	    let allocator = Allocator::default();
37	    let source_type = SourceType::from_path(path).unwrap_or_default();
38	    let ret = Parser::new(&allocator, source, source_type).parse();
39	
40	    // .d.ts declaration files use the same React.FC / ForwardRefExoticComponent patterns as .tsx
41	    let is_tsx = source_type.is_jsx() || source_type.is_typescript_definition();
42	    let mut collector = SourceDataCollector::new(path, source, is_tsx);
43	    // Pass comments by cloning them into owned strings before the allocator drops.
44	    // The comments Vec lives in the arena; we extract them here.
45	    let comments: Vec<OwnedComment> = ret
46	        .program
47	        .comments
48	        .iter()
49	        .map(|c| OwnedComment { span_start: c.span.start, span_end: c.span.end, is_block: c.is_block() })
50	        .collect();
51	    collector.comments = comments;
52	    collector.visit_program(&ret.program);
53	    collector.finish()
54	    // allocator drops here — ALL arena memory freed
55	}
