3	/// Walk `src_dirs` and collect every `.ts` / `.tsx` file, excluding:
4	/// - Built-in patterns: `.stories.`, `.test.`, `.spec.`, `__snapshots__`, `node_modules`
5	/// - User-supplied extra exclude patterns
6	pub(super) fn discover_files(src_dirs: &[Utf8PathBuf], extra_excludes: &[String]) -> Vec<Utf8PathBuf> {
7	    let mut files = Vec::new();
8	
9	    for dir in src_dirs {
10	        // If the user explicitly points at a node_modules path, respect it.
11	        let dir_str = dir.as_str();
12	        let dir_is_in_node_modules = dir_str.contains("node_modules");
13	
14	        let walker =
15	            ignore::WalkBuilder::new(dir.as_std_path()).hidden(false).git_ignore(!dir_is_in_node_modules).build();
16	
17	        for entry in walker.flatten() {
18	            let path = entry.path();
19	            let ext = path.extension().and_then(|e| e.to_str()).unwrap_or("");
20	            if !matches!(ext, "ts" | "tsx") {
21	                continue;
22	            }
23	
24	            let path_str = path.to_str().unwrap_or("");
25	
26	            // Built-in excludes — skip node_modules sub-dirs only when not intentionally targeting them.
27	            if path_str.contains(".stories.")
28	                || path_str.contains(".test.")
29	                || path_str.contains(".spec.")
30	                || path_str.contains("__snapshots__")
31	                || (!dir_is_in_node_modules && path_str.contains("node_modules"))
32	            {
33	                continue;
34	            }
35	
36	            // User-supplied excludes.
37	            if extra_excludes.iter().any(|p| path_str.contains(p.as_str())) {
38	                continue;
39	            }
40	
41	            if let Ok(utf8) = Utf8PathBuf::from_path_buf(path.to_owned()) {
42	                files.push(utf8);
43	            }
44	        }
45	    }
46	
47	    files.sort(); // deterministic ordering across OS / FS
48	    files
49	}
