11	/// Map a React builtin type name to the appropriate `PropType`.
12	pub(super) fn react_type_to_prop_type(
13	    name: &str,
14	    args: &[CollectedType],
15	    consuming_file: &Utf8Path,
16	    ctx: &ResolutionContext,
17	    state: &mut ResolveState,
18	    depth: u8,
19	) -> PropType {
20	    // Strip "React." prefix for matching.
21	    let strip = name.strip_prefix("React.").unwrap_or(name);
22	
23	    match strip {
24	        // React node types.
25	        "ReactNode" | "ReactElement" | "JSX.Element" | "ReactPortal" | "ReactFragment" | "ReactChild" => {
26	            PropType::ReactNode
27	        }
28	
29	        // CSS properties.
30	        "CSSProperties" | "CSSObject" => PropType::CssProperties,
31	
32	        // Named event handlers (e.g. MouseEventHandler).
33	        n if n.ends_with("EventHandler") || n.ends_with("Handler") => {
34	            PropType::EventHandler { event_type: name.to_owned(), param_name: None }
35	        }
36	
37	        // Synthetic and DOM events — the type IS the event type.
38	        "SyntheticEvent" | "MouseEvent" | "KeyboardEvent" | "ChangeEvent" | "FocusEvent" | "FormEvent"
39	        | "DragEvent" | "TouchEvent" | "WheelEvent" | "AnimationEvent" | "TransitionEvent" | "ClipboardEvent"
40	        | "CompositionEvent" | "PointerEvent" => {
41	            let raw_args: Vec<String> = args.iter().map(|a| a.to_raw_string()).collect();
42	            let event_type =
43	                if raw_args.is_empty() { name.to_owned() } else { format!("{}<{}>", name, raw_args.join(", ")) };
44	            PropType::EventHandler { event_type, param_name: None }
45	        }
46	
47	        // Ref types.
48	        "Ref" | "RefObject" | "ForwardedRef" | "MutableRefObject" | "RefCallback" | "LegacyRef" => {
49	            let element = args.first().map(|a| a.to_raw_string());
50	            PropType::Ref { element }
51	        }
52	
53	        // ElementType — component-as-prop.
54	        "ElementType" => PropType::ElementType,
55	
56	        // FC / FunctionComponent — return as Named.
57	        "FC"
58	        | "FunctionComponent"
59	        | "VFC"
60	        | "VoidFunctionComponent"
61	        | "ComponentType"
62	        | "ForwardRefExoticComponent" => {
63	            let resolved_args: Vec<PropType> =
64	                args.iter().map(|a| resolve_collected_type(a, consuming_file, ctx, state, depth + 1)).collect();
65	            PropType::Named { name: name.into(), args: resolved_args }
66	        }
67	
68	        // ComponentPropsWithoutRef<'button'> or ComponentPropsWithoutRef<typeof X>.
69	        "ComponentPropsWithoutRef" | "ComponentProps" | "ComponentPropsWithRef" => {
70	            if let Some(first) = args.first() {
71	                match first {
72	                    CollectedType::StringLiteral(el) => {
73	                        PropType::HtmlAttributes { element: el.to_lowercase().to_string(), omitted: vec![] }
74	                    }
75	                    other => PropType::Named {
76	                        name: name.into(),
77	                        args: vec![resolve_collected_type(other, consuming_file, ctx, state, depth + 1)],
78	                    },
79	                }
80	            } else {
81	                PropType::Any
82	            }
83	        }
84	
85	        // PropsWithChildren / PropsWithRef — resolve inner type.
86	        "PropsWithChildren" | "PropsWithRef" => {
87	            if let Some(first) = args.first() {
88	                resolve_collected_type(first, consuming_file, ctx, state, depth + 1)
89	            } else {
90	                PropType::Any
91	            }
92	        }
93	
