10	    /// Find JSDoc comment immediately preceding the given byte offset.
11	    /// Returns empty string if none found.
12	    ///
13	    /// Marks the comment as consumed so subsequent calls for a different span cannot
14	    /// return the same comment (prevents prop JSDoc leaking into component descriptions).
15	    ///
16	    /// `self.comments` is sorted by span (source order), so the candidate window is
17	    /// located via binary search rather than a linear scan — callers run one of these
18	    /// per prop/interface/component, and a full rescan-per-call is quadratic in file size.
19	    pub(super) fn find_jsdoc(&mut self, span_start: u32) -> String {
20	        const PROXIMITY_THRESHOLD: u32 = 120; // bytes — enough for blank lines + decorator
21	
22	        let upper = self.comments.partition_point(|c| c.span_end <= span_start);
23	        let mut found: Option<usize> = None;
24	        for i in (0..upper).rev() {
25	            let c = &self.comments[i];
26	            if span_start - c.span_end > PROXIMITY_THRESHOLD {
27	                // Comments are sorted ascending by span, so every earlier comment
28	                // is farther still — nothing left in range.
29	                break;
30	            }
31	            if c.is_block && !self.consumed_jsdoc.contains(&c.span_end) {
32	                found = Some(i);
33	                break;
34	            }
35	        }
36	
37	        match found {
38	            Some(i) => {
39	                let c = &self.comments[i];
40	                let span_end = c.span_end;
41	                let raw = &self.source[c.span_start as usize..c.span_end as usize];
42	                let text = parse_jsdoc_text(raw);
43	                if !text.is_empty() {
44	                    self.consumed_jsdoc.insert(span_end);
45	                }
46	                text
47	            }
48	            None => String::new(),
49	        }
50	    }
51	
52	    /// Extract JSDoc @tags from the comment preceding the given byte offset.
53	    pub(super) fn extract_jsdoc_tags(&self, span_start: u32) -> BTreeMap<String, String> {
54	        const PROXIMITY_THRESHOLD: u32 = 120;
55	
56	        let upper = self.comments.partition_point(|c| c.span_end <= span_start);
57	        let comment = (0..upper).rev().find_map(|i| {
58	            let c = &self.comments[i];
59	            if span_start - c.span_end > PROXIMITY_THRESHOLD {
60	                return None;
61	            }
62	            c.is_block.then_some(c)
63	        });
64	
65	        match comment {
66	            Some(c) => {
67	                let raw = &self.source[c.span_start as usize..c.span_end as usize];
68	                extract_jsdoc_tags(raw)
69	            }
70	            None => BTreeMap::new(),
71	        }
72	    }
