27	                let layer = InheritedLayer {
28	                    type_name: name.to_string(),
29	                    file_name: resolve_react_types_file(iface_file, ctx),
30	                    omitted: vec![],
31	                    html_element: Some(element_name.clone()),
32	                    total_props: 0, // unknown without type-checker
33	                };
34	                (ResolvedChain::default(), Some(layer))
35	            } else {
36	                // Non-HTML-element builtins. ComponentPropsWithoutRef/ComponentProps:
37	                // expand directly to HtmlAttributes based on the first type arg.
38	                let bare = name.as_str().strip_prefix("React.").unwrap_or(name.as_str());
39	                if matches!(bare, "ComponentPropsWithoutRef" | "ComponentPropsWithRef" | "ComponentProps") {
40	                    if let Some(raw_arg) = type_args.first() {
41	                        let inner = raw_arg.trim().trim_matches('"').trim_matches('\'');
42	                        if !inner.is_empty() {
43	                            let layer = InheritedLayer {
44	                                type_name: name.to_string(),
45	                                file_name: resolve_react_types_file(iface_file, ctx),
46	                                omitted: vec![],
47	                                html_element: Some(inner.to_lowercase()),
48	                                total_props: 0,
49	                            };
50	                            return (ResolvedChain::default(), Some(layer));
51	                        }
52	                    }
53	                }
54	                // Other non-HTML builtins (PropsWithChildren, ElementRef, etc.)
