5	///
6	/// Returns `Ok(None)` when no config file exists anywhere between `start_dir` and the
7	/// workspace root — callers fall back to [`PipelineOptions::default`]. Returns `Err` when
8	/// a config file IS found but can't be honored; see [`try_load_config`].
9	pub fn load_config_file(start_dir: &std::path::Path) -> Result<Option<PipelineOptions>> {
10	    let mut dir = start_dir;
11	    loop {
12	        let candidate = dir.join("docgen.config.ts");
13	        if candidate.exists() {
14	            return try_load_config(&candidate);
15	        }
16	        // Stop at workspace root signals
17	        for signal in &["pnpm-workspace.yaml", "turbo.json", ".moon/workspace.yml"] {
18	            if dir.join(signal).exists() {
19	                return Ok(None);
20	            }
21	        }
22	        let Some(parent) = dir.parent() else { return Ok(None) };
23	        dir = parent;
24	    }
