27	/// Execute and validate `docgen.config.ts` at `path`.
28	///
29	/// Mapping the config's JSON schema onto [`PipelineOptions`] isn't implemented yet, so a
30	/// config that evaluates successfully still can't be honored. Returning `Ok(None)` here
31	/// would mean a config a user explicitly wrote (e.g. with different `srcDirs`) gets
32	/// silently ignored in favor of defaults — a plausible-looking but wrong result forever
33	/// (crates/core/CLAUDE.md non-negotiable #6: never fail silently). So any config file that
34	/// is *found* is a hard error until schema mapping ships.
35	pub fn try_load_config(path: &std::path::Path) -> Result<Option<PipelineOptions>> {
36	    use std::io::Write;
37	
38	    // Pass the config path via environment variable to avoid any path content
39	    // being interpreted as JavaScript (command injection via crafted filenames).
40	    let script = "import { pathToFileURL } from 'node:url';\
41	        const p = process.env.__DOCGEN_CONFIG_PATH;\
42	        const m = await import(pathToFileURL(p).href);\
43	        process.stdout.write(JSON.stringify(m.default ?? m));";
44	
45	    let mut child = std::process::Command::new("node")
46	        .args(["--input-type=module"])
47	        .env("NODE_OPTIONS", "--import=tsx/esm")
48	        .env("__DOCGEN_CONFIG_PATH", path)
49	        .stdin(std::process::Stdio::piped())
50	        .stdout(std::process::Stdio::piped())
51	        .stderr(std::process::Stdio::null())
52	        .spawn()
53	        .into_diagnostic()?;
54	
55	    // Write the script to stdin, then close stdin to signal EOF.
56	    let mut stdin =
57	        child.stdin.take().ok_or_else(|| miette::miette!("failed to open stdin for the node subprocess"))?;
58	    stdin.write_all(script.as_bytes()).into_diagnostic()?;
59	    drop(stdin);
60	
61	    let output = child.wait_with_output().into_diagnostic()?;
62	
63	    if !output.status.success() {
64	        return Err(miette::miette!(
65	            help = "Check docgen.config.ts for syntax errors, or remove it to use defaults.",
66	            "docgen.config.ts at {} failed to evaluate ({})",
67	            path.display(),
68	            output.status,
69	        ));
70	    }
71	
72	    // Parse as JSON to confirm the config at least evaluates to a valid object.
73	    serde_json::from_slice::<serde_json::Value>(&output.stdout).into_diagnostic()?;
74	
75	    Err(miette::miette!(
76	        help = "Remove docgen.config.ts (or drop --config) to use CLI flags and defaults instead.",
77	        "docgen.config.ts was found at {} but config file support is not yet implemented in this version",
78	        path.display(),
