55	    /// built once per resolution pass so `resolve_typeof` and
56	    /// `resolve_cva_variant_props` (VariantProps<typeof X>) can do an O(1)
57	    /// lookup instead of a linear scan with a `format!()` allocation per
58	    /// candidate on every reference. Ambiguous bare names (same name in two
59	    /// files) resolve to whichever key `global.enums` yields first during
60	    /// this build pass — the same tie-break the old linear scan produced,
61	    /// since both iterate the same underlying map.
62	    pub enum_bare_index: FxHashMap<CompactString, CompactString>,
63	}
