67	        let alias: Vec<(String, Vec<AliasValue>)> = react::read_tsconfig_paths(options.tsconfig_path.as_deref());
68	
69	        let resolve_options = ResolveOptions {
70	            condition_names: vec!["types".into(), "import".into(), "require".into(), "default".into()],
71	            main_fields: vec!["types".into(), "typings".into(), "module".into(), "main".into()],
72	            extensions: vec![".ts".into(), ".tsx".into(), ".d.ts".into(), ".js".into()],
