77	        let mut enum_bare_index: FxHashMap<CompactString, CompactString> = FxHashMap::default();
78	        for key in global.enums.keys() {
79	            let bare = key.rsplit_once(':').map(|(_, name)| name).unwrap_or(key.as_str());
80	            enum_bare_index.entry(CompactString::from(bare)).or_insert_with(|| CompactString::from(key.as_str()));
81	        }
82	
83	        Self {
84	            import_map: Arc::new(ImportResolutionMap::build(&global)),
85	            global,
86	            oxc_resolver: Arc::new(Resolver::new(resolve_options)),
