     pub(super) fn lookup_interface<'g>(global: &'g GlobalSourceData, canonical_file: &str, canonical_name: &str) -> Option<&'g CollectedInterface> {
         global.interfaces.get(&format!("{canonical_file}:{canonical_name}"))
             .or_else(|| global.interfaces.get(&format!("{canonical_file}:React.{canonical_name}")))
     }
     pub(super) fn lookup_type_alias<'g>(global: &'g GlobalSourceData, canonical_file: &str, canonical_name: &str) -> Option<(String, &'g CollectedTypeAlias)> {
         let bare_key = format!("{canonical_file}:{canonical_name}");
         if let Some(alias) = global.type_aliases.get(&bare_key) { return Some((bare_key, alias)); }
         let qualified_key = format!("{canonical_file}:React.{canonical_name}");
         global.type_aliases.get(&qualified_key).map(|alias| (qualified_key, alias))
     }
