     pub(super) fn lookup_ambient_global<'g>(ctx: &'g ResolutionContext, name: &str) -> Option<AmbientGlobalLookup<'g>> {
         for lib_file in &ctx.ambient_global_files {
             let key = format!("{lib_file}:{name}");
             if ctx.global.interfaces.contains_key(&key) { return Some(AmbientGlobalLookup::Interface); }
             if let Some(alias) = ctx.global.type_aliases.get(&key) { return Some(AmbientGlobalLookup::TypeAlias(alias)); }
         }
