12	pub(super) fn resolve_function_type(
13	    params: &[CollectedType],
14	    param_names: &[Option<CompactString>],
15	    return_type: &CollectedType,
16	    consuming_file: &Utf8Path,
17	    ctx: &ResolutionContext,
18	    state: &mut ResolveState,
19	    depth: u8,
20	) -> PropType {
21	    // Check if the return type is a React node → render prop pattern.
22	    let returns_react_node = matches!(
23	        return_type,
24	        CollectedType::Named { name, .. }
25	            if matches!(
26	                name.as_str(),
27	                "ReactNode"
28	                    | "ReactElement"
29	                    | "JSX.Element"
30	                    | "Element"
31	                    | "ReactPortal"
32	                    | "ReactFragment"
33	            )
34	    );
35	
36	    let first_param_name = || param_names.first().and_then(|n| n.as_ref()).map(|s| s.to_string());
37	
38	    if returns_react_node && params.len() == 1 {
39	        let event_type = params[0].to_raw_string();
40	        return PropType::EventHandler { event_type, param_name: first_param_name() };
41	    }
42	
43	    // Generic event handler: (e: SomeEvent) => void
44	    if params.len() == 1 {
45	        let event_type = params[0].to_raw_string();
46	        return PropType::EventHandler { event_type, param_name: first_param_name() };
47	    }
48	
49	    // Zero-arg callback: () => void
50	    if params.is_empty() {
51	        return PropType::EventHandler { event_type: "void".into(), param_name: None };
52	    }
53	
54	    // Multi-param function — describe as opaque.
55	    let param_strs: Vec<String> = params.iter().map(|p| p.to_raw_string()).collect();
56	    let raw = format!("({}) => {}", param_strs.join(", "), return_type.to_raw_string());
57	
58	    // Resolve the return type to see if it's ReactNode.
59	    let _ = resolve_collected_type(return_type, consuming_file, ctx, state, depth + 1);
60	
61	    PropType::Opaque { raw, reason: OpaqueReason::ConditionalType }
62	}
