51	                computed: false,
52	                source: DefaultSource::Destructuring,
53	            },
54	            Expression::NumericLiteral(n) => {
55	                RawDefault { value: n.value.to_string(), computed: false, source: DefaultSource::Destructuring }
56	            }
57	            Expression::BooleanLiteral(b) => {
58	                RawDefault { value: b.value.to_string(), computed: false, source: DefaultSource::Destructuring }
59	            }
60	            Expression::NullLiteral(_) => {
61	                RawDefault { value: "null".into(), computed: false, source: DefaultSource::Destructuring }
62	            }
63	            Expression::Identifier(id) if id.name.as_str() == "undefined" => {
