128	    pub fn update_file(&self, changed: &Utf8Path) -> IncrementalUpdate {
129	        let start = Instant::now();
130	
131	        // 1. Re-parse the changed file.
132	        let mut io_diagnostic: Option<Diagnostic> = None;
133	        let source = match std::fs::read_to_string(changed) {
134	            Ok(s) => s,
135	            Err(e) => {
136	                io_diagnostic = Some(Diagnostic {
137	                    severity: DiagnosticSeverity::Error,
138	                    message: format!("Failed to read '{}': {}", changed, e),
139	                    file: Some(changed.to_string()),
140	                    line: None,
141	                    column: None,
142	                    help: Some("Check file permissions and that the file exists.".into()),
143	                    code: DiagnosticCode::IoError,
144	                });
145	                String::new()
146	            }
147	        };
148	        let new_data = crate::extractor::parse_file(changed, &source);
149	        self.source_cache.insert(changed.to_owned(), new_data.clone());
150	
151	        // 2. Patch GlobalSourceData atomically using rcu (read-copy-update).
152	        // rcu retries if the pointer was swapped by a concurrent update_file call,
153	        // preventing lost-update races under parallel file change events.
154	        let new_global = self.global.rcu(|old| {
155	            let mut g = (**old).clone();
156	            g.remove_file(changed);
157	            g.merge(changed, new_data.clone());
158	            g
159	        });
160	
161	        // 3. Find all transitively affected files via the reverse dep graph.
162	        let affected = self.reverse_deps.affected(changed);
163	
164	        // 4. Re-resolve affected components.
165	        let affected_mappings: Vec<ComponentMapping> =
166	            new_global.component_mappings.iter().filter(|m| affected.contains(&m.file_path)).cloned().collect();
167	
168	        let ctx = ResolutionContext::new(new_global.clone(), &self.options);
169	        let results: Vec<(ComponentEntry, Vec<Diagnostic>)> =
170	            affected_mappings.par_iter().map(|m| resolve_component(m, &ctx)).collect();
171	
172	        let mut updated_components = Vec::new();
173	        let mut diagnostics: Vec<Diagnostic> = io_diagnostic.into_iter().collect();
174	
175	        for (entry, diags) in results {
176	            self.component_cache.insert(entry.display_name.clone(), entry.clone());
177	            updated_components.push(entry);
178	            diagnostics.extend(diags);
179	        }
180	
181	        // Replace (not append) this file's diagnostics — a fixed file's prior
182	        // errors shouldn't linger in subsequent snapshots.
183	        if diagnostics.is_empty() {
184	            self.diagnostics.remove(changed);
185	        } else {
186	            self.diagnostics.insert(changed.to_owned(), diagnostics.clone());
187	        }
188	
189	        IncrementalUpdate {
190	            updated_components,
191	            affected_files: affected.into_iter().collect(),
192	            diagnostics,
193	            duration_ms: start.elapsed().as_millis() as u64,
