153	    /// BFS: collect all files transitively affected by a change to `changed`.
154	    pub fn affected(&self, changed: &Utf8Path) -> FxHashSet<Utf8PathBuf> {
155	        let mut visited: FxHashSet<Utf8PathBuf> = Default::default();
156	        let mut queue: VecDeque<Utf8PathBuf> = VecDeque::new();
157	        queue.push_back(changed.to_owned());
158	
159	        while let Some(file) = queue.pop_front() {
160	            if visited.insert(file.clone()) {
161	                for dep in self.inner.get(&file).into_iter().flatten() {
162	                    queue.push_back(dep.clone());
163	                }
164	            }
165	        }
166	
167	        visited
168	    }
