13	    members: &[CollectedType],
14	    consuming_file: &Utf8Path,
15	    ctx: &ResolutionContext,
16	    state: &mut ResolveState,
17	    depth: u8,
18	) -> PropType {
19	    // Filter out `undefined` from optional unions: `string | undefined` → `string`
20	    // (the `required: false` on the prop already captures optionality).
21	    let meaningful: Vec<&CollectedType> = members.iter().filter(|m| !matches!(m, CollectedType::Undefined)).collect();
22	
23	    let to_resolve = if meaningful.is_empty() { members.iter().collect::<Vec<_>>() } else { meaningful };
24	
25	    let resolved: Vec<PropType> =
26	        to_resolve.iter().map(|m| resolve_collected_type(m, consuming_file, ctx, state, depth + 1)).collect();
27	
28	    // Flatten nested Unions.
29	    let mut flat: Vec<PropType> = Vec::with_capacity(resolved.len());
30	    for pt in resolved {
31	        if let PropType::Union(inner) = pt {
32	            flat.extend(inner);
33	        } else {
34	            flat.push(pt);
35	        }
36	    }
37	
38	    if flat.len() == 1 {
39	        flat.remove(0)
40	    } else {
41	        PropType::Union(flat)
42	    }
43	}
