76	pub(super) fn resolve_typeof(
77	    name: &CompactString,
78	    consuming_file: &Utf8Path,
79	    ctx: &ResolutionContext,
80	    diagnostics: &mut Vec<Diagnostic>,
81	) -> PropType {
82	    // `typeof X` — look for X in global.enums (for cva() results), via the
83	    // precomputed bare-name index (O(1) instead of a linear scan over every
84	    // enum/cva/tv/recipe entry in the project with a per-candidate allocation).
85	    let found_enum = ctx.enum_bare_index.get(name.as_str()).and_then(|key| ctx.global.enums.get(key.as_str()));
86	
87	    if found_enum.is_some() {
88	        // Has cva-like enum entries — the VariantProps<typeof X> pattern handles this.
89	        // At the type level, surface as Named.
90	        return PropType::Named { name: name.clone(), args: vec![] };
91	    }
92	
93	    diagnostics.push(Diagnostic {
94	        severity: DiagnosticSeverity::Info,
95	        message: format!("typeof '{}' in '{}' — could not statically evaluate", name, consuming_file),
96	        file: Some(consuming_file.to_string()),
97	        line: None,
98	        column: None,
99	        help: None,
100	        code: DiagnosticCode::OpaqueType,
101	    });
102	
103	    PropType::Named { name: name.clone(), args: vec![] }
