177	    /// Builds the cache key from the file's current size + mtime.
178	    ///
179	    /// Known limitation: staleness detection is mtime+size only, no content
180	    /// hash. On filesystems with coarse mtime resolution (e.g. some
181	    /// configurations report only 1-second granularity), an edit that lands
182	    /// in the same tick as a prior write *and* happens to produce a
183	    /// same-length file will be served a stale cache hit — the key looks
184	    /// unchanged even though the content differs. A content hash would close
185	    /// this gap but trades away the cheap stat-only check this cache relies
186	    /// on for its speed; see `docs/root-cause-analysis.md` — this is a
187	    /// deliberate, scoped-for-later tradeoff, not an oversight.
188	    fn key_for(&self, path: &Utf8Path) -> Option<CacheKey> {
189	        let meta = std::fs::metadata(path.as_std_path()).ok()?;
190	        let mtime_ns = meta
191	            .modified()
192	            .ok()
193	            .and_then(|t| t.duration_since(SystemTime::UNIX_EPOCH).ok())
194	            .map(|d| d.as_nanos())
195	            .unwrap_or(0);
196	
197	        Some(CacheKey { path: path.to_owned(), size: meta.len(), mtime_ns })
198	    }
