13	/// Writes `contents` to `path` via a same-directory temp file + rename, so a
14	/// mid-write failure (disk full, permission revoked) can never leave `path`
15	/// truncated or half-written. Returns the `io::Error` on failure instead of
16	/// swallowing it — callers must report it, not discard the `Result`.
17	fn write_atomic(path: &str, contents: &str) -> std::io::Result<()> {
18	    let target = std::path::Path::new(path);
19	    let dir = match target.parent() {
20	        Some(p) if !p.as_os_str().is_empty() => p,
21	        _ => std::path::Path::new("."),
22	    };
23	    let file_name = target.file_name().ok_or_else(|| {
24	        std::io::Error::new(std::io::ErrorKind::InvalidInput, format!("'{path}' has no file name component"))
25	    })?;
26	    let mut tmp_name = std::ffi::OsString::from(".");
27	    tmp_name.push(file_name);
28	    tmp_name.push(".tmp");
29	    let tmp_path = dir.join(tmp_name);
30	    if let Err(e) = std::fs::write(&tmp_path, contents) {
31	        let _ = std::fs::remove_file(&tmp_path);
32	        return Err(e);
33	    }
34	    if let Err(e) = std::fs::rename(&tmp_path, target) {
35	        let _ = std::fs::remove_file(&tmp_path);
36	        return Err(e);
37	    }
38	    Ok(())
39	}
